import{_ as o,o as a,c as t,ag as n}from"./chunks/framework.B7PviQjB.js";const i="/docs/images/files/pdfs-comment-on-text.png",l="/docs/images/files/pdfs-comments-panel.png",u=JSON.parse('{"title":"Read and comment on PDFs","description":"Read a PDF in the browser, copy its text, comment on text or a region of a page, and download the original.","frontmatter":{"title":"Read and comment on PDFs","description":"Read a PDF in the browser, copy its text, comment on text or a region of a page, and download the original.","type":"how-to"},"headers":[],"relativePath":"files/pdfs.md","filePath":"files/pdfs.md"}'),s={name:"files/pdfs.md"};function r(h,e,d,c,m,p){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="read-and-comment-on-pdfs" tabindex="-1">Read and comment on PDFs <a class="header-anchor" href="#read-and-comment-on-pdfs" aria-label="Permalink to &quot;Read and comment on PDFs&quot;">​</a></h1><p>Read an uploaded PDF in the browser, copy its text, and discuss it with comments pinned to the page.</p><p>A PDF is view-only: you can&#39;t change its contents in Wafflebase. Comments sit over the page and never change the file.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>To add a PDF, <a href="/docs/files/upload.html">upload</a> a <code>.pdf</code> file of up to 50 MB.</li><li>Anyone who can open the PDF can read it. To comment, you need to be a workspace member or have an <strong>Editor</strong> <a href="/docs/collaborate/share.html">share link</a>.</li></ul></div><h2 id="read-a-pdf" tabindex="-1">Read a PDF <a class="header-anchor" href="#read-a-pdf" aria-label="Permalink to &quot;Read a PDF&quot;">​</a></h2><ol><li>Open the PDF from your documents list.</li><li>Scroll to move through the pages.</li></ol><p>The pages appear in one continuous column, each fitted to the width of the window up to a maximum width. A progress bar shows while the file loads. There is no zoom control; resize the window or collapse the sidebar to change the page width.</p><h2 id="select-and-copy-text" tabindex="-1">Select and copy text <a class="header-anchor" href="#select-and-copy-text" aria-label="Permalink to &quot;Select and copy text&quot;">​</a></h2><ol><li>Drag across the text you want.</li><li>Press <code>⌘+C</code> / <code>Ctrl+C</code>.</li></ol><p>To find a word, use your browser&#39;s find (<code>⌘+F</code> / <code>Ctrl+F</code>). It searches the pages you have already scrolled to.</p><p>A scanned page has no text to select. To comment on it, use <a href="#comment-on-a-region">a region comment</a>.</p><h2 id="comment-on-selected-text" tabindex="-1">Comment on selected text <a class="header-anchor" href="#comment-on-selected-text" aria-label="Permalink to &quot;Comment on selected text&quot;">​</a></h2><ol><li>Select the text you want to comment on.</li><li>Click <strong>Comment</strong> below the selection.</li><li>Type your comment. The selected text is quoted above the box.</li><li>Click <strong>Comment</strong> to post it.</li></ol><p>The commented text stays highlighted until the thread is resolved, and the comment appears for everyone who has the PDF open.</p><p><img src="'+i+'" alt="A sentence selected in a PDF with the Comment button below it"></p><h2 id="comment-on-a-region" tabindex="-1">Comment on a region <a class="header-anchor" href="#comment-on-a-region" aria-label="Permalink to &quot;Comment on a region&quot;">​</a></h2><p>Use a region comment for a scanned page, a figure, or a table.</p><ol><li>Click the speech-bubble icon with a plus (<strong>Comment on a region</strong>) in the header. The button is highlighted while the tool is on.</li><li>Drag a rectangle over the part of the page.</li><li>Type your comment and click <strong>Comment</strong>.</li></ol><p>The comment is pinned to that area of that page. To cancel the tool before you drag, click the icon again.</p><h2 id="reply-to-and-resolve-comments" tabindex="-1">Reply to and resolve comments <a class="header-anchor" href="#reply-to-and-resolve-comments" aria-label="Permalink to &quot;Reply to and resolve comments&quot;">​</a></h2><ol><li>Click the speech-bubble icon (<strong>Show comments</strong>) in the header.</li><li>Select a thread. The list labels each thread with its page, such as <strong>Page 3</strong>.</li><li>Reply, resolve or reopen the thread, or edit or delete your own comments.</li></ol><p>The panel has <strong>Open</strong> and <strong>Resolved</strong> tabs, each with a count. Clicking a pin on the page opens its thread. For more about threads, see <a href="/docs/collaborate/comments.html">Comments</a>.</p><p><img src="'+l+'" alt="PDF with the comments panel open, listing two threads labeled Page 1 and Page 2"></p><h2 id="download-the-original" tabindex="-1">Download the original <a class="header-anchor" href="#download-the-original" aria-label="Permalink to &quot;Download the original&quot;">​</a></h2><p>Click the download icon (<strong>Download PDF</strong>) in the header. The original file downloads unchanged, without comments. Only people who can open the PDF can download it.</p><h2 id="see-who-else-is-reading" tabindex="-1">See who else is reading <a class="header-anchor" href="#see-who-else-is-reading" aria-label="Permalink to &quot;See who else is reading&quot;">​</a></h2><p>Avatars in the header show who else has the PDF open. They show who is reading, not which page they are on.</p><h2 id="rename-a-pdf" tabindex="-1">Rename a PDF <a class="header-anchor" href="#rename-a-pdf" aria-label="Permalink to &quot;Rename a PDF&quot;">​</a></h2><p>Click the title in the header, type a new name, and press <code>Enter</code>.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>The PDF fits the screen width, and the header keeps the same buttons. If the header is crowded, swipe the row of buttons sideways to reach the rest. See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>There is no zoom, page navigation, or annotation tool. Comments are the only markup.</li><li>A <strong>Viewer</strong> share link opens the PDF marked <strong>View only</strong>. Viewers can read comments but not add them.</li><li>A share link page has no download button. To give someone the original file, send it to them separately.</li><li>To change a PDF, edit it in another app and upload the new version.</li><li>If a PDF fails to load, the viewer shows <code>Couldn&#39;t open this PDF. Reload the page to try again.</code></li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/files/upload.html">Upload files</a> to add more PDFs.</li><li><a href="/docs/collaborate/share.html">Share a document</a> to send the PDF to reviewers.</li><li><a href="/docs/collaborate/comments.html">Comments</a> to learn how threads work across Wafflebase.</li></ul>',35)])])}const f=o(s,[["render",r]]);export{u as __pageData,f as default};
